    T(std::initializer_list<type> init); // Constructor accepting initializer_list
};

// Using uniform initialization:
T obj = {value1, value2, value3};

code_example:
#include <iostream>
#include <vector>
#include <initializer_list>

class MyContainer {
public:
    std::vector<int> data;
    // Constructor accepting initializer_list
    MyContainer(std::initializer_list<int> init) : data(init) {}
    void print() const {
        for (auto val : data) {
            std::cout << val << ' ';
        }
        std::cout << std::endl;
    }
};

int main() {
    // Initialize container with list of values using uniform initialization
    MyContainer container = {1, 2, 3, 4, 5};
    container.print();
    return 0;
}
